/* Start here entry for giant-planets (demos/lib/starthere/giant-planets.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"Saturn has 95 times Earth's mass. Would it sink or float in water?","q_es":"Saturno tiene 95 veces la masa de la Tierra. ¿Se hundiría o flotaría en agua?","setup":"set=selSpeed~3600!chkEarth~1!labBlind~0!g%3Apresets~float","do":"Saturn beside the other giants and Earth, all to scale. Decide whether Saturn would sink or float in a big enough tub, then read <b>Mean density</b> and <b>Floats in water?</b> under Readouts and compare the density bars below the planets with the water line.","do_es":"Saturno junto a los otros gigantes y la Tierra, todos a escala. Decide si Saturno se hundiría o flotaría en una tina lo bastante grande, luego lee <b>Densidad media</b> y <b>¿Flota en agua?</b> en Lecturas en pantalla y compara las barras de densidad bajo los planetas con la línea del agua.","see":"Saturn's mean density is 0.687 g/cm³, less than water's 1.00, so it would float. It has 95.16 times Earth's mass, but 764 Earths fit inside it, and 95.16/764 of Earth's 5.514 g/cm³ is 0.687 g/cm³. Saturn is mostly hydrogen and helium, the lightest gases, and it is the only planet less dense than water.","see_es":"La densidad media de Saturno es 0.687 g/cm³, menor que la del agua, 1.00, así que flotaría. Tiene 95.16 veces la masa de la Tierra, pero dentro caben 764 Tierras, y 95.16/764 de los 5.514 g/cm³ de la Tierra da 0.687 g/cm³. Saturno es sobre todo hidrógeno y helio, los gases más ligeros, y es el único planeta menos denso que el agua.","explore":[{"setup":"set=selSpeed~3600!selPlanet~saturn!sRho~920!sDist~1.4!chkRoche~1!chkRes~0!labBlind~0!g%3AmodeSeg~rings!g%3Apresets~tear","do":"<b>A moon torn into a ring</b>: a moon of solid ice at 1.40 Saturn radii, inside its <b>Roche limit, fluid moon</b> of 2.15 R. Decide whether it holds together, then press <b>Reset</b> and <b>Play</b> and watch <b>Largest piece</b>.","do_es":"<b>Una luna despedazada en un anillo</b>: una luna de hielo sólido a 1.40 radios de Saturno, dentro de su <b>Límite de Roche, luna fluida</b> de 2.15 R. Decide si se mantiene unida, luego presiona <b>Reiniciar</b> e <b>Iniciar</b> y observa <b>Pedazo más grande</b>.","see":"Before the first orbit (6.95 h) is over, the largest piece is under 10 % of the moon, and the pieces string out along the orbit. Saturn pulls the moon's near side harder than its far side, and inside the Roche limit that stretch beats the moon's own gravity. Saturn's bright rings lie inside this limit.","see_es":"Antes de que termine la primera órbita (6.95 h), el pedazo más grande es menos del 10 % de la luna, y los pedazos se alinean a lo largo de la órbita. Saturno jala el lado cercano de la luna más fuerte que el lejano, y dentro del límite de Roche ese estiramiento le gana a la propia gravedad de la luna. Los anillos brillantes de Saturno están dentro de este límite."},{"setup":"set=selSpeed~3600!selPlanet~saturn!sRho~3000!sDist~1.5!chkRoche~1!chkRes~0!labBlind~0!g%3AmodeSeg~rings!g%3AboxRings.Test%20moon%20made%20of~3000!g%3Apresets~rock","do":"<b>A rock moon survives</b>: a moon of rock, 3.0 g/cm³, at 1.50 Saturn radii, well inside the ice moon's limit. Predict what happens, then press <b>Reset</b> and <b>Play</b> and compare <b>Largest piece</b> and <b>Roche limit, fluid moon</b> with the ice moon's.","do_es":"<b>Una luna de roca sobrevive</b>: una luna de roca, de 3.0 g/cm³, a 1.50 radios de Saturno, muy dentro del límite de la luna de hielo. Predice qué pasa, luego presiona <b>Reiniciar</b> e <b>Iniciar</b> y compara <b>Pedazo más grande</b> y <b>Límite de Roche, luna fluida</b> con los de la luna de hielo.","see":"It stays whole, 100 % orbit after orbit. A denser moon holds itself together more tightly, so its Roche limit is closer in: 2.15 R × (0.92/3.0)<sup>1/3</sup> = 1.45 R, just inside the moon's 1.50 R.","see_es":"Se queda entera, 100 % órbita tras órbita. Una luna más densa se mantiene unida con más fuerza, así que su límite de Roche está más cerca: 2.15 R × (0.92/3.0)<sup>1/3</sup> = 1.45 R, justo dentro de los 1.50 R de la luna."},{"setup":"set=selSpeed~86400!selPlanet~jupiter!selMoon~0!chkConj~1!chkNb~0!labBlind~0!g%3AmodeSeg~moons!g%3Apresets~galilean","do":"<b>Io, Europa, Ganymede 1:2:4</b>: Jupiter's big moons, starting where they were on 1 January 2000. Can all three ever line up on one side of Jupiter? Decide, then press <b>Reset</b> and <b>Play</b> and watch the lines where pairs of moons pass.","do_es":"<b>Ío, Europa, Ganímedes 1:2:4</b>: las lunas grandes de Júpiter, empezando donde estaban el 1 de enero de 2000. ¿Pueden las tres alinearse alguna vez del mismo lado de Júpiter? Decide, luego presiona <b>Reiniciar</b> e <b>Iniciar</b> y observa las líneas donde pasan los pares de lunas.","see":"Io goes round 2.007 times for each orbit of Europa, and Europa 2.015 times for each orbit of Ganymede (the ÷ inner column). Each pair always passes near the same places, and λ(Io) − 3λ(Europa) + 2λ(Ganymede) stays at 180.0°, so the three never line up together. These regular tugs keep Io's orbit oval, and the changing tide heats Io.","see_es":"Ío da 2.007 vueltas por cada órbita de Europa, y Europa 2.015 por cada órbita de Ganímedes (la columna ÷ interior). Cada par pasa siempre cerca de los mismos lugares, y λ(Ío) − 3λ(Europa) + 2λ(Ganímedes) se queda en 180.0°, así que las tres nunca se alinean juntas. Estos jalones regulares mantienen ovalada la órbita de Ío, y la marea cambiante calienta a Ío."}]});
